const TRANSLATIONS = { en: ENGLISH, ru: { ...ENGLISH, ...RUSSIAN }, es: { ...ENGLISH, ...SPANISH }, de: { ...ENGLISH, ...GERMAN }, fr: { ...ENGLISH, ...FRENCH }, "pt-BR": { ...ENGLISH, ...PORTUGUESE } };

export function t(locale = "en", key, variables = {}) {
  const text = (TRANSLATIONS[locale] || ENGLISH)[key] || ENGLISH[key] || key;
  return text.replace(/\{(\w+)\}/g, (_, name) => variables[name] ?? "");
}

export function languageName(locale, language) {
  const keys = { Russian: "languageRussian", English: "languageEnglish", Spanish: "languageSpanish", German: "languageGerman", French: "languageFrench", "Brazilian Portuguese": "languagePortuguese" };
  return t(locale, keys[language] || language);
}

export function localizePage(locale) {
  document.documentElement.lang = locale;
  document.querySelectorAll("[data-i18n]").forEach((element) => { element.textContent = t(locale, element.dataset.i18n); });
  document.querySelectorAll("[data-i18n-title]").forEach((element) => { element.title = t(locale, element.dataset.i18nTitle); });
  document.querySelectorAll("[data-i18n-aria]").forEach((element) => { element.setAttribute("aria-label", t(locale, element.dataset.i18nAria)); });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((element) => { element.placeholder = t(locale, element.dataset.i18nPlaceholder); });
}
